/** Prefab instantiate + scene tree spawn (Unity/Godot). */

import type { EntityDef, SpawnDef, ZoneDef } from "../manifest.ts";
import { isSpawnDef } from "../manifest.ts";
import type { Groups } from "../kernel/groups.ts";
